import{_ as n,a8 as o,o as i,c as s,ah as l,K as a}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const b=JSON.parse('{"title":"ambient-care · Demo 设计决策 D1-D19","description":"","frontmatter":{"type":"decision","scope":"ambient-care","created":"2026-09-13T00:00:00.000Z","updated":"2026-09-13T00:00:00.000Z","tags":["ambient-care","decision","养老","ASR","Demo"]},"headers":[],"relativePath":"vault/Memory/Decisions/ambient-care-Demo设计决策D1-D19.md","filePath":"vault/Memory/Decisions/ambient-care-Demo设计决策D1-D19.md","lastUpdated":1789374053000}'),c={name:"vault/Memory/Decisions/ambient-care-Demo设计决策D1-D19.md"};function d(m,e,D,g,u,h){const r=o("NolebaseGitContributors"),t=o("NolebaseGitChangelog");return i(),s("div",null,[e[0]||(e[0]=l('<h1 id="ambient-care-·-demo-设计决策-d1-d19" tabindex="-1">ambient-care · Demo 设计决策 D1-D19 <a class="header-anchor" href="#ambient-care-·-demo-设计决策-d1-d19" aria-label="Permalink to “ambient-care · Demo 设计决策 D1-D19”">​</a></h1><blockquote><p>蒸馏自项目内 <code>.memory/decisions.md</code>（原文已归档至项目 <code>.memory/_archive/</code>）。每条含日期背景与影响，完整版见归档原文；项目原则「不确定的设计先记 Decision，不擅定」。</p></blockquote><h2 id="mvp-范围类-2026-08-12-13" tabindex="-1">MVP 范围类（2026-08-12/13） <a class="header-anchor" href="#mvp-范围类-2026-08-12-13" aria-label="Permalink to “MVP 范围类（2026-08-12/13）”">​</a></h2><ul><li><strong>D1 单人居室假设</strong>：MVP 跳过说话人分离（pyannote 成本高），Event.resident_id 由 Room 推导可空；diarization 列 Future。</li><li><strong>D2 合成数据</strong>：Demo 数据集=TTS 合成+开源数据集（Common Voice/VoxCeleb 噪声段）；禁止采集真实老人音频。</li><li><strong>D3 告警仅站内</strong>：Dashboard 高亮+标记；wecom/短信 Future，架构预留 Webhook/MQ。</li><li><strong>D4 音频留存</strong>：仅留通过有效语音过滤的片段+转写；原始 24h 音频只短期缓存调试，留存期限待合规细化。</li><li><strong>D5 MVP=单次 LLM 结构化调用</strong>，不称 Agent；真 Agent（工具调用/长期记忆/推理循环/RAG）全部 Future。</li><li><strong>D7 event_type 收窄</strong>：仅 casual/health/emergency/unknown；behavior/environment 推迟。</li><li><strong>D8 误报治理</strong>：VAD 阈值 0.5/最短 0.3s；有效语音=时长≥1.0s&amp;能量阈值&amp;ASR 非空；confidence&lt;0.4 降 unknown；emergency 需关键词命中 AND confidence≥0.6 否则降 health；risk∈{high,critical} 才建 Alert。</li><li><strong>D9 无声紧急盲区标注</strong>：老人跌倒/昏迷无法出声 100% 漏检，写入已知局限，诚实对外，Future 多模态补位。</li><li><strong>D10 MVP≠合规声明</strong>：隐私=全合成+本地短留存（默认 7 天）；真实知情同意/加密/不出域/审计留 Future。</li></ul><h2 id="demo-收敛类-2026-08-13" tabindex="-1">Demo 收敛类（2026-08-13） <a class="header-anchor" href="#demo-收敛类-2026-08-13" aria-label="Permalink to “Demo 收敛类（2026-08-13）”">​</a></h2><ul><li><strong>D11 范围收敛</strong>：Demo=本机实时对话转写，移除 FastAPI/React/PostgreSQL/Docker，无 DB/Web。</li><li><strong>D12 产出形态</strong>：完整转录(去无关)+按「居家适老需求沟通评估表」8 维度关键词标注（不做 LLM 摘要）；<code>summarize.py</code> 改 <code>classify.py</code>，LLM 降为可选。</li></ul><h2 id="技术选型类-2026-08-13" tabindex="-1">技术选型类（2026-08-13） <a class="header-anchor" href="#技术选型类-2026-08-13" aria-label="Permalink to “技术选型类（2026-08-13）”">​</a></h2><ul><li><strong>D13 ASR Spike</strong>：云端 Qwen3-ASR 被 DASHSCOPE_API_KEY 门禁无法实测；FunASR Paraformer-zh 本地实测通过（CPU infer 0.77s，RTF≈0.11-0.14≈7×实时）。pip 26 沙箱 safe-delete 安装失败，需 dangerouslyDisableSandbox+<code>--no-cache-dir</code>。</li><li><strong>D14 主选切换本地 Qwen3-ASR 0.6B</strong>（qwen-asr 包，无 key 离线）：CPU RTF≈0.71 可跟实时；核显装 IPEX 后 xpu:0 提速；HF 可能被墙，权重由 ModelScope 预下载到本地目录 <code>from_pretrained(local_dir)</code>（或 HF_ENDPOINT=hf-mirror.com）。两个隔离 venv。</li><li><strong>D15 全链路模块落地</strong>：capture/classify/session/output/main 全本地无 Web 无 DB；classify 纯关键词毫秒级。</li><li><strong>D16 常驻 ASR 服务</strong>：<code>asr_service.py</code> 纯标准库 HTTP，解决反复自测加载慢；客户端 <code>--asr-url</code> 透传，零新增依赖。</li><li><strong>D17-D19 GUI 三步走</strong>：tkinter 零依赖极简 GUI（D17）→ 按 ui-design-system 视觉升级（Material3 care 调色板+卡片层级+录音脉冲+8 维度 chips+转写高亮，D18）→ 按钮交互重做（开始/停止同一主按钮切换+独立暂停；待机不自动录音；关闭窗口录音中先报告，D19）。</li></ul>',8)),a(r),a(t)])}const P=n(c,[["render",d]]);export{b as __pageData,P as default};
